package com.bank.sequence.service;

import java.util.logging.Logger;

// Computes the Nth Fibonacci term bottom-up with constant space.
public class SequenceModelService {
    private static final Logger log = Logger.getLogger(SequenceModelService.class.getName());

    public long fib(int n) {
        if (n < 2) return n;                        // fib(0)=0, fib(1)=1
        long prev2 = 0, prev1 = 1;                  // last two terms only
        for (int i = 2; i <= n; i++) {
            long cur = prev1 + prev2;               // current = sum of previous two
            prev2 = prev1;
            prev1 = cur;
        }
        final long r = prev1;
        log.info(() -> "fib(" + n + ") = " + r);
        return prev1;
    }
}
